INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v2_portugues_aplicacao','Simulado de Português — leitura e argumentação','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','portugues','["Inferência","Coesão referencial","Argumentação","Adequação linguística","Gêneros textuais"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_portugues_aplicacao_q1','nivora_enem_v2_portugues_aplicacao','Em uma crônica fictícia, o narrador diz: “A praça ganhou internet, mas perdeu as conversas. Sentados lado a lado, todos olhavam para longe, dentro das telas.” A crítica central recai sobre:','O contraste entre estar lado a lado e olhar para as telas sugere distanciamento social na presença física. O trecho não informa custos nem condena todo uso de tecnologia.','Inferência',0,2) ON CONFLICT(id) DO NOTHING;
