INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_portugues_aplicacao_q2','nivora_enem_v2_portugues_aplicacao','Leia: “A escola abriu a biblioteca aos sábados. Essa iniciativa ampliou o acesso dos moradores aos livros.” A expressão “essa iniciativa” retoma:','O demonstrativo retoma uma ação apresentada na frase anterior: abrir a biblioteca aos sábados. Ele mantém a continuidade do texto sem repetir toda a informação.','Coesão referencial',1,1) ON CONFLICT(id) DO NOTHING;
