INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_portugues_aplicacao_q3','nivora_enem_v2_portugues_aplicacao','Um anúncio fictício afirma: “Nove em cada dez entrevistados preferem nosso produto”, mas não informa quem foi entrevistado nem o tamanho da amostra. Uma leitura crítica deve:','Sem conhecer amostra e método, não é possível avaliar a representatividade da pesquisa. Isso não prova que o dado seja falso; limita a conclusão que ele sustenta.','Argumentação',2,3) ON CONFLICT(id) DO NOTHING;
