INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_portugues_aplicacao_q4','nivora_enem_v2_portugues_aplicacao','Uma estudante escreve uma mensagem informal para um amigo e um pedido de bolsa para uma instituição. Ao adaptar o registro ao segundo destinatário, ela deve:','A adequação depende de finalidade, interlocutor e contexto. Um pedido institucional pede clareza e registro apropriado, sem hierarquizar o valor pessoal de quem usa outras variedades.','Adequação linguística',3,0) ON CONFLICT(id) DO NOTHING;
