INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_portugues_aplicacao_q5','nivora_enem_v2_portugues_aplicacao','Um texto apresenta a posição de um jornal sobre a preservação de parques, com argumentos e propostas, sem assinatura individual. Essas características aproximam-no de:','O editorial expressa a posição institucional de um veículo sobre uma questão relevante. Argumentação e ausência de assinatura individual são características comuns desse gênero.','Gêneros textuais',4,4) ON CONFLICT(id) DO NOTHING;
