INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_quimica_aplicacao_q5','nivora_enem_v2_quimica_aplicacao','Dois comprimidos idênticos reagem separadamente em iguais volumes de água, à mesma temperatura. Um está inteiro e o outro foi triturado. A trituração tende a aumentar a velocidade porque:','Para uma reação com sólido, maior superfície exposta pode favorecer o contato entre reagentes. Triturar não exige mudar composição, massa ou temperatura.','Cinética química',4,2) ON CONFLICT(id) DO NOTHING;
