INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v2_humanas_aplicacao','Simulado de Humanas — sociedade e território','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','humanas','["Cartografia","Urbanização","Fontes históricas","Trabalho e industrialização","Sustentabilidade"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_humanas_aplicacao_q1','nivora_enem_v2_humanas_aplicacao','Um mapa tem escala 1:100 000 e outro 1:1 000 000. Para representar detalhes de um bairro, mantendo a mesma qualidade cartográfica, o mais adequado é o primeiro porque:','1/100000 é maior que 1/1000000. Em uma escala maior, cada centímetro corresponde a menos espaço real, permitindo mais detalhes.','Cartografia',0,1) ON CONFLICT(id) DO NOTHING;
INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v2_humanas_aplicacao_q1_o0','nivora_enem_v2_humanas_aplicacao_q1','Sua escala é menor e elimina detalhes.',0) ON CONFLICT(id) DO NOTHING;
