INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v2_humanas_aplicacao_q1_o2','nivora_enem_v2_humanas_aplicacao_q1','Ambos têm necessariamente o mesmo detalhamento.',2) ON CONFLICT(id) DO NOTHING;
