INSERT INTO question_options (id,question_id,texto,ordem) VALUES ('nivora_enem_v2_humanas_aplicacao_q1_o4','nivora_enem_v2_humanas_aplicacao_q1','A escala não relaciona mapa e território.',4) ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_humanas_aplicacao_q2','nivora_enem_v2_humanas_aplicacao','Uma metrópole apresenta moradias populares distantes dos empregos e transporte coletivo insuficiente. Uma consequência provável dessa organização é:','A distância entre moradia e emprego, combinada a transporte insuficiente, pode aumentar o ônus de deslocamento. O enunciado não sustenta conclusões absolutas sobre todos os bairros.','Urbanização',1,3) ON CONFLICT(id) DO NOTHING;
