INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_humanas_aplicacao_q3','nivora_enem_v2_humanas_aplicacao','Ao estudar um período, uma pesquisadora compara um jornal, cartas e fotografias, considerando autores e contextos de produção. Esse procedimento busca:','Fontes são produzidas em contextos e por sujeitos. Compará-las permite avaliar perspectivas, interesses e limites, sem presumir neutralidade absoluta.','Fontes históricas',2,4) ON CONFLICT(id) DO NOTHING;
