INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_humanas_aplicacao_q4','nivora_enem_v2_humanas_aplicacao','Na produção industrial em série, trabalhadores realizam etapas especializadas e repetitivas. Em comparação com a produção artesanal integral, isso expressa:','A divisão técnica distribui etapas entre trabalhadores e setores, aumentando sua interdependência. Não significa que cada trabalhador domine o processo completo.','Trabalho e industrialização',3,0) ON CONFLICT(id) DO NOTHING;
