INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v2_humanas_aplicacao_q5','nivora_enem_v2_humanas_aplicacao','Uma cidade amplia a coleta seletiva, mas os materiais separados acabam misturados ao lixo comum antes do destino final. Para efetivar a reciclagem, é necessário:','Separar na origem é uma etapa. A reciclagem depende de uma cadeia que preserve a separação, faça triagem e encaminhe materiais para aproveitamento adequado.','Sustentabilidade',4,2) ON CONFLICT(id) DO NOTHING;
